<template><main class="setup-page"><section class="setup-card"><div class="icon">✦</div><p class="eyebrow">ONE LAST STEP</p><h1>绑定你的学习模型</h1><p class="intro">首次绑定后，Key 会加密保存在你的账户中；下次登录无需再次输入。</p><div class="model"><div><b>DeepSeek</b><small>当前试点唯一开放模型 · 支持专属学习 Agent</small></div><span>已选择</span></div><el-form label-position="top"><el-form-item label="DeepSeek API Key"><el-input v-model="apiKey" type="password" show-password placeholder="sk-..." autocomplete="off"/></el-form-item></el-form><div class="notice">🔒 密钥仅用于代表你调用模型，数据库只保存加密内容，页面不会再次显示完整 Key。</div><button class="main-button" :disabled="saving" @click="save">{{saving?'正在安全保存…':'安全保存并开始学习 →'}}</button><button class="back" @click="logout">退出登录</button></section></main></template>
<script setup>import{ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';const router=useRouter(),apiKey=ref(''),saving=ref(false);async function save(){if(!apiKey.value.trim())return ElMessage.warning('请输入 DeepSeek API Key');saving.value=true;try{const res=await fetch('/api/user/apikey',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('token')}`},body:JSON.stringify({model_type:'deepseek',api_key:apiKey.value.trim()})}),data=await res.json();if(!res.ok)return ElMessage.error(data.error||'保存失败');const user=JSON.parse(localStorage.getItem('user')||'{}');user.hasApiKey=true;user.model_type='deepseek';localStorage.setItem('user',JSON.stringify(user));ElMessage.success('已安全保存，欢迎使用 CampusMind');router.push('/dashboard')}catch{ElMessage.error('无法连接后端服务')}finally{saving.value=false}}function logout(){localStorage.removeItem('token');localStorage.removeItem('user');router.push('/login')}</script>
<style scoped>.setup-page{min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 15% 18%,#ffe6d5,transparent 28%),radial-gradient(circle at 88% 82%,#f9d6bd,transparent 30%),#fff9f4}.setup-card{width:min(480px,100%);box-sizing:border-box;background:#fffdfa;border:1px solid #f0dfd4;border-radius:28px;padding:36px;box-shadow:0 18px 50px #8d45221a;text-align:center}.icon{margin:auto;width:56px;height:56px;display:grid;place-items:center;border-radius:20px;background:#c96d42;color:#fff;font-size:26px}.eyebrow{font-size:11px;letter-spacing:1.5px;font-weight:800;color:#bd7659;margin:19px 0 5px}.setup-card h1{color:#603a2a;margin:0;font-size:29px}.intro{color:#96786a;line-height:1.65;margin:10px 0 24px}.model{display:flex;justify-content:space-between;text-align:left;align-items:center;background:#fff0e5;border:1px solid #f2d1bf;border-radius:17px;padding:14px;margin-bottom:20px;color:#73412d}.model small{display:block;color:#a27360;font-size:12px;margin-top:4px}.model span{font-size:12px;color:#b35533;font-weight:800}.setup-card :deep(.el-form-item__label){font-weight:700;color:#765c50}.setup-card :deep(.el-input__wrapper){border-radius:13px;box-shadow:0 0 0 1px #ead8cd inset;padding:4px 12px}.notice{font-size:12px;line-height:1.65;text-align:left;color:#937568;background:#fff9f4;border-radius:13px;padding:11px;margin:18px 0}.main-button{width:100%;border:0;border-radius:14px;padding:13px;background:#c96d42;color:#fff;font-weight:800;cursor:pointer}.main-button:disabled{opacity:.7}.back{border:0;background:none;color:#ae6041;margin-top:16px;cursor:pointer}</style>
